import{_ as l,a0 as a,w as p,s,I as n,x as o,a1 as i,A as r,ao as g}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"尝试 H2o 做机器学习 | LCTT x X-CMD","titleTemplate":false,"description":"尝试 H2o 做机器学习 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"尝试 H2o 做机器学习 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"尝试 H2o 做机器学习 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180314 Playing with water","title":"尝试 H2o 做机器学习","tag":"201804","desc":""},"relativePath":"201804/20180314 Playing with water.md","filePath":"[post].md"}'),d={name:"201804/20180314 Playing with water.md"};function m(w,t,u,f,T,H){const e=a("Link");return p(),s("div",null,[t[18]||(t[18]=n("h1",{id:"尝试-h2o-做机器学习",tabindex:"-1"},[o("尝试 H2o 做机器学习 "),n("a",{class:"header-anchor",href:"#尝试-h2o-做机器学习","aria-label":"Permalink to “尝试 H2o 做机器学习”"},"​")],-1)),t[19]||(t[19]=n("p",null,[n("img",{src:"https://veronneau.org/media/blog/2018-03-14/h2o_job.png",alt:"H2o Flow gradient boosting job",title:"H2o Flow gradient boosting job"})],-1)),n("p",null,[t[2]||(t[2]=o("我目前正在参加一个机器学习班，虽然工作量很疯狂，但我非常喜欢。我最初计划使用 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/R_(programming_language)"},{default:r(()=>[...t[0]||(t[0]=[o("R",-1)])]),_:1}),t[3]||(t[3]=o(" 来训练我的数据库，但老师建议我使用一个 FOSS 机器学习框架 ",-1)),i(e,{href:"https://www.h2o.ai"},{default:r(()=>[...t[1]||(t[1]=[o("H2o",-1)])]),_:1}),t[4]||(t[4]=o("。",-1))]),t[20]||(t[20]=g('<p>起初我有点怀疑，因为我已经对 R 掌握得不错了，但后来我发现你可以简单地将 H2o 作为 R 库导入。H2o 将大多数 R 函数替换为其自己的并行化函数，以减少处理时间（不再需要 <code>doParallel</code> 调用），并且使用“外部”服务端来运行，而不是直接调用 R。</p><p><img src="https://veronneau.org/media/blog/2018-03-14/h2o_model.png" alt="H2o Flow gradient boosting model" title="H2o Flow gradient boosting model"></p><p>直到我真正在实际中开始在 H2o 中使用 R 时，我对这种情况都非常满意。我在使用非常大的数据库时，库变得笨重，我几乎不能做任何有用得事情。大多数时候，我最后只是得到一个很长的 Java 回溯调用。</p><p>我相信正确地将 H2o 作为一个库使用将非常强大，但可惜的是，它似乎在我的 R 技能中无效。</p><p><img src="https://veronneau.org/media/blog/2018-03-14/h2o_var_importance.png" alt="H2o Flow variable importance weights" title="H2o Flow variable importance weights"></p><p>我生了一整天的气 —— 无法实现我想做的事 —— 直到我意识到 H2o 有一个名为 Flow 的 WebUI。我通常不喜欢使用 web 来完成重要的工作，比如编写代码，但是 Flow 简直太不可思议了。</p><p>自动绘图功能，运行资源密集模型时集成 ETA（预计剩余时间），每个模型参数的描述（这些参数甚至会根据您熟悉的统计模型分成不同部分），Flow 似乎拥有所有功能。我很快就能够运行 3 种基本的机器学习模型并获得实际可解释的结果。</p><p>所以，如果你一直渴望使用最先进的机器学习模型分析非常大的数据库，我会推荐使用 H2o。首先尝试使用 Flow，而不是 Python 或 R 的钩子，来看看它能做什么。</p><p>唯一缺点是，H2o 是用 Java 编写的，并依赖 Java 1.7 来运行。并且需要警告的是：它需要非常强大的处理器和大量的内存。即使有 10 个可用的内核和 10Gb 的 RAM，我可怜的服务器也苦苦挣扎了一段时间。</p><hr>',10)),n("p",null,[t[6]||(t[6]=o("via: ",-1)),i(e,{href:"https://veronneau.org/playing-with-water.html"},{default:r(()=>[...t[5]||(t[5]=[o("https://veronneau.org/playing-with-water.html",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=o("作者：",-1)),i(e,{href:"https://veronneau.org/"},{default:r(()=>[...t[7]||(t[7]=[o("Louis-Philippe Véronneau",-1)])]),_:1}),t[11]||(t[11]=o(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:r(()=>[...t[8]||(t[8]=[o("geekpi",-1)])]),_:1}),t[12]||(t[12]=o(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中国",-1)])]),_:1}),t[17]||(t[17]=o(" 荣誉推出",-1))])])}const x=l(d,[["render",m]]);export{C as __pageData,x as default};
